 	readState struct {
@@ -832,10 +834,29 @@ func (d *DB) applyInternal(batch *Batch, opts *WriteOptions, noSyncWait bool) er
 			return err
 		}
 	}
+	if sync && !d.opts.DisableWAL && !batch.Empty() {
+		batch.durability = &batchDurabilityState{
+			db:            d,
+			correlationID: opts.GetCommitCorrelationID(),
+			batchSize:     len(batch.Repr()),
+			keyCount:      batch.Count(),
+			startTime:     crtime.NowMono(),
